  out.sort((a, b) => {
    const tr = tierRank(a.trustTier) - tierRank(b.trustTier);
    if (tr !== 0) return tr;
    return b.trustScore - a.trustScore;
  });
  return out;
}

// ---------------------------------------------------------------------------
// De-duplication: DOI → PMID → fuzzy title (preprint collapses into published).
// ---------------------------------------------------------------------------

function dedupeCitations(citations) {
  const byKey = new Map();
  const order = [];
  for (const c of citations) {
    const key = dedupeKey(c);
    if (byKey.has(key)) {
      // Merge: prefer the published (non-preprint) record, keep max citedBy.
      const existing = byKey.get(key);
      byKey.set(key, mergeCitations(existing, c));
    } else {
      byKey.set(key, c);
      order.push(key);
    }
  }
  return order.map((k) => byKey.get(k));
}

function dedupeKey(c) {
  if (c.doi) return 'doi:' + String(c.doi).toLowerCase().trim();
  if (c.pmid) return 'pmid:' + String(c.pmid).trim();
  // fuzzy: normalized title
  const t = String(c.title || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
  return 'title:' + t.slice(0, 80);
}

function mergeCitations(a, b) {
  // Prefer the one that is NOT a preprint and HAS more metadata.
  const primary = a.isPreprint && !b.isPreprint ? b : a;
  const other = primary === a ? b : a;
  return {
    ...other,
    ...primary,
    citedBy: Math.max(a.citedBy || 0, b.citedBy || 0) || primary.citedBy,
    pubTypes: dedupeArr([...(a.pubTypes || []), ...(b.pubTypes || [])]),
    meshTerms: dedupeArr([...(a.meshTerms || []), ...(b.meshTerms || [])]),
    doi: primary.doi || other.doi,
    pmid: primary.pmid || other.pmid,
    medlineIndexed: a.medlineIndexed || b.medlineIndexed,
  };
}

function dedupeArr(arr) {
  return Array.from(new Set(arr.filter(Boolean)));
}

// ---------------------------------------------------------------------------
// Source: PubMed E-utilities (esearch + esummary)
// ---------------------------------------------------------------------------

function ncbiCommonParams() {
  const p = new URLSearchParams();
  p.set('tool', NCBI_TOOL);
  p.set('email', NCBI_EMAIL);
  if (NCBI_API_KEY) p.set('api_key', NCBI_API_KEY);
  return p;
}

async function pubmedSearch(query, maxResults) {
  const citations = [];
  try {
    // 1) esearch → PMIDs
    const esearchParams = ncbiCommonParams();
    esearchParams.set('db', 'pubmed');
    esearchParams.set('term', query);
    esearchParams.set('retmax', String(Math.min(Math.max(maxResults, 1), 50)));
    esearchParams.set('retmode', 'json');
    esearchParams.set('sort', 'relevance');
    const esearchUrl = `${EUTILS_BASE}/esearch.fcgi?${esearchParams.toString()}`;
    const esearch = await ncbiLimiter(() => httpGetJson(esearchUrl));
    const idlist =
      (esearch && esearch.esearchresult && esearch.esearchresult.idlist) || [];
    if (idlist.length === 0) return citations;

    // 2) esummary → metadata for each PMID
    const esummaryParams = ncbiCommonParams();
    esummaryParams.set('db', 'pubmed');
    esummaryParams.set('id', idlist.join(','));
    esummaryParams.set('retmode', 'json');
    const esummaryUrl = `${EUTILS_BASE}/esummary.fcgi?${esummaryParams.toString()}`;
    const esummary = await ncbiLimiter(() => httpGetJson(esummaryUrl));
    const result = (esummary && esummary.result) || {};
    const uids = result.uids || idlist;

    uids.forEach((uid, idx) => {
      const r = result[uid];
      if (!r) return;
      citations.push(normalizePubmed(r, uid, idx, idlist.length, query));
    });
  } catch (e) {
    log('pubmed error:', e.message);
  }
  return citations;
}

function normalizePubmed(r, uid, idx, total, query) {
  const pubTypes = Array.isArray(r.pubtype) ? r.pubtype.slice() : [];
  const year = parseYear(r.pubdate || r.epubdate || r.sortpubdate);
  let doi = '';
  if (Array.isArray(r.articleids)) {
    const d = r.articleids.find((a) => a.idtype === 'doi');
    if (d) doi = d.value;
  }
  const journal = r.fulljournalname || r.source || '';
  const titleLc = String(r.title || '').toLowerCase();
  const titleBoost = queryTerms(query).some((t) => t.length > 3 && titleLc.includes(t));
  // MEDLINE-indexed heuristic: pubstatus/records carrying a full journal name + MeSH.
  const medlineIndexed = !!r.fulljournalname;
  return {
    id: doi ? `doi:${doi}` : `pmid:${uid}`,
    source: 'PubMed',
    title: cleanText(r.title),
    journal,
    year,
    pubTypes,
    meshTerms: [], // esummary does not return MeSH; computeTier handles the gap via fallback
    url: `https://pubmed.ncbi.nlm.nih.gov/${uid}/`,
    doi,
    pmid: String(uid),
    citedBy: undefined,
    isPreprint: pubTypes.some((p) => /preprint/i.test(p)),
    commentsCorrections: [],
    medlineIndexed,
    _apiRelevance: total > 0 ? 1 - idx / Math.max(total, 1) : 0.6,
    _titleBoost: titleBoost,
  };
}

// ---------------------------------------------------------------------------
// Source: Europe PMC REST (preprints + citedByCount + isOpenAccess)
// ---------------------------------------------------------------------------

async function europePmcSearch(query, maxResults) {
  const citations = [];
  try {
    const params = new URLSearchParams();
    params.set('query', query);
    params.set('format', 'json');
    params.set('pageSize', String(Math.min(Math.max(maxResults, 1), 50)));
    params.set('resultType', 'core');
    const url = `${EUROPEPMC_BASE}/search?${params.toString()}`;
    const data = await generalLimiter(() => httpGetJson(url));
    const results =
      (data && data.resultList && data.resultList.result) || [];
    results.forEach((r, idx) => {
      citations.push(normalizeEuropePmc(r, idx, results.length, query));
    });
  } catch (e) {
    log('europepmc error:', e.message);
  }
  return citations;
}

function normalizeEuropePmc(r, idx, total, query) {
  const pubTypes = [];
  if (r.pubTypeList && Array.isArray(r.pubTypeList.pubType)) {
    pubTypes.push(...r.pubTypeList.pubType);
  } else if (typeof r.pubType === 'string') {
    pubTypes.push(r.pubType);
  }
  const meshTerms = [];
  if (r.meshHeadingList && Array.isArray(r.meshHeadingList.meshHeading)) {
    for (const m of r.meshHeadingList.meshHeading) {
      if (m && m.descriptorName) meshTerms.push(m.descriptorName);
    }
  }
  const isPreprint =
    String(r.source || '').toUpperCase() === 'PPR' ||
    pubTypes.some((p) => /preprint/i.test(p));
  const doi = r.doi || '';
  const pmid = r.pmid || '';
  const year = parseYear(r.firstPublicationDate || r.pubYear);
  const journal =
    (r.journalInfo && r.journalInfo.journal && r.journalInfo.journal.title) ||
    r.journalTitle ||
    (isPreprint ? 'Preprint' : '');
  const titleLc = String(r.title || '').toLowerCase();
  const titleBoost = queryTerms(query).some((t) => t.length > 3 && titleLc.includes(t));
  let url = '';
  if (doi) url = `https://doi.org/${doi}`;
  else if (pmid) url = `https://europepmc.org/abstract/MED/${pmid}`;
  else if (r.id && r.source) url = `https://europepmc.org/abstract/${r.source}/${r.id}`;
  return {
    id: doi ? `doi:${doi}` : pmid ? `pmid:${pmid}` : `epmc:${r.source}-${r.id}`,
    source: 'EuropePMC',
    title: cleanText(r.title),
    journal,
    year,
    pubTypes,
    meshTerms,
    url,
    doi,
    pmid: pmid ? String(pmid) : '',
    citedBy: typeof r.citedByCount === 'number' ? r.citedByCount : undefined,
    isPreprint,
    isOpenAccess: r.isOpenAccess === 'Y',
    commentsCorrections: [],
    medlineIndexed: String(r.source || '').toUpperCase() === 'MED',
    _apiRelevance: total > 0 ? 1 - idx / Math.max(total, 1) : 0.6,
    _titleBoost: titleBoost,
  };
}

// ---------------------------------------------------------------------------
// Tool: search_literature
// ---------------------------------------------------------------------------

async function tool_search_literature(args) {
  const query = String(args.query || '').trim();
  const maxResults = clampInt(args.maxResults, 8, 1, 25);
  const tierFilter = normalizeTierFilter(args.tierFilter);

  if (!query) {
    return { citations: [], note: 'No query provided.', disclaimer: NCBI_DISCLAIMER };
  }

  // Fan out to both corpora in parallel; each fails independently.
  const fetchCount = Math.min(maxResults * 2, 25); // over-fetch to survive de-dup
  const [pm, epmc] = await Promise.all([
    pubmedSearch(query, fetchCount),
    europePmcSearch(query, fetchCount),
  ]);

  const merged = dedupeCitations([...pm, ...epmc]);
  let ranked = rankCitations(merged); // drops retracted

  if (tierFilter && tierFilter.length) {
    ranked = ranked.filter((c) => tierFilter.includes(c.trustTier));
  }

  // Hard stage cap: never return tiers below the user's selected research stage, whatever the model asked for.
  const stageTiers = STAGE_TIERS[RESEARCH_STAGE];
  const beforeStage = ranked.length;
  ranked = ranked.filter((c) => stageTiers.includes(c.trustTier));
  const stageDropped = beforeStage - ranked.length;

  const top = ranked.slice(0, maxResults).map(shapeCitationOut);

  const note =
    top.length === 0
      ? `No citations matched at research stage ${RESEARCH_STAGE} (${STAGE_NAME[RESEARCH_STAGE]}). ` +
        (stageDropped > 0
          ? `${stageDropped} lower-tier result(s) were withheld by the stage cap — raise the research stage to include earlier evidence.`
          : 'Try a broader query.')
      : `Returned ${top.length} ranked citation(s) from PubMed + Europe PMC at research stage ${RESEARCH_STAGE} (${STAGE_NAME[RESEARCH_STAGE]}). Retracted publications were dropped.` +
        (stageDropped > 0 ? ` ${stageDropped} lower-tier result(s) were withheld by the stage cap.` : '');

  return {
    query,
    researchStage: RESEARCH_STAGE,
    researchStageName: STAGE_NAME[RESEARCH_STAGE],
    citations: top,
    counts: { pubmed: pm.length, europepmc: epmc.length, afterDedup: merged.length, afterRank: beforeStage, afterStageCap: ranked.length },
    disclaimer: NCBI_DISCLAIMER,
    note,
  };
}

function shapeCitationOut(c) {
  const maturity = maturityForTier(c.trustTier);
  return {
    id: c.id,
    source: c.source,
    title: c.title,
    journal: c.journal || null,
    year: c.year || null,
    pubTypes: c.pubTypes || [],
    url: c.url,
    doi: c.doi || null,
    pmid: c.pmid || null,
    citedBy: typeof c.citedBy === 'number' ? c.citedBy : null,
    trustTier: c.trustTier,
    trustScore: c.trustScore,
    concern: c.concern || false,
    whyTrusted: c.whyTrusted,
    maturity,
    caution: cautionForTier(c.trustTier),
  };
}

// ---------------------------------------------------------------------------
// Tool: find_trials — ClinicalTrials.gov API v2
// ---------------------------------------------------------------------------

async function tool_find_trials(args) {
  const condition = String(args.condition || '').trim();
  let status = String(args.status || 'RECRUITING').trim().toUpperCase();
  const maxResults = clampInt(args.maxResults, 8, 1, 25);

  if (!condition) {
    return { trials: [], note: 'No condition provided.' };
  }

  // Ongoing (recruiting / not-yet-completed) trials are frontier evidence. At stages 1–2 they fall
  // outside the selected research maturity, so only surface COMPLETED trials there.
  let stageNote = '';
  if (RESEARCH_STAGE <= 2 && status !== 'COMPLETED') {
    stageNote = ` Research stage ${RESEARCH_STAGE} (${STAGE_NAME[RESEARCH_STAGE]}) excludes ongoing trials, so this was restricted to COMPLETED trials — raise the research stage to see recruiting studies.`;
    status = 'COMPLETED';
  }

  const trials = [];
  try {
    const params = new URLSearchParams();
    params.set('query.cond', condition);
    params.set('pageSize', String(maxResults));
    params.set('countTotal', 'true');
    // Status filter (CT.gov v2 accepts a pipe-separated overallStatus filter).
    if (status && status !== 'ANY' && status !== 'ALL') {
      params.set('filter.overallStatus', status);
    }
    // Only request the fields we need.
    params.set(
      'fields',
      [
        'NCTId',
        'BriefTitle',
        'OverallStatus',
        'Phase',
        'Condition',
        'LocationCountry',
        'LocationFacility',
      ].join(',')
    );
    const url = `${CTGOV_BASE}?${params.toString()}`;
    const data = await generalLimiter(() => httpGetJson(url));
    const studies = (data && data.studies) || [];
    for (const s of studies) {
      trials.push(normalizeTrial(s));
    }
  } catch (e) {
    log('ctgov error:', e.message);
    return {
      condition,
      status,
      trials: [],
      note: `ClinicalTrials.gov request failed (${e.message}). Returning an empty list.`,
    };
  }

  return {
    condition,
    status,
    researchStage: RESEARCH_STAGE,
    trials,
    note:
      (trials.length === 0
        ? `No ${status} trials found for "${condition}".`
        : `Found ${trials.length} trial(s) for "${condition}" with status ${status}.`) + stageNote,
  };
}

function normalizeTrial(s) {
  const proto = s.protocolSection || {};
  const idMod = proto.identificationModule || {};
  const statusMod = proto.statusModule || {};
  const designMod = proto.designModule || {};
  const condMod = proto.conditionsModule || {};
  const contactsMod = proto.contactsLocationsModule || {};
  const nctId = idMod.nctId || '';
  const locations = Array.isArray(contactsMod.locations) ? contactsMod.locations : [];
  const overallStatus = statusMod.overallStatus || '';
  const completed = String(overallStatus).toUpperCase() === 'COMPLETED';
  return {
    nctId,
    title: idMod.briefTitle || idMod.officialTitle || '',
    status: overallStatus,
    phase: Array.isArray(designMod.phases) ? designMod.phases.join(', ') : (designMod.phases || 'N/A'),
    conditions: Array.isArray(condMod.conditions) ? condMod.conditions : [],
    url: nctId ? `https://clinicaltrials.gov/study/${nctId}` : '',
    locationsCount: locations.length,
    countries: dedupeArr(locations.map((l) => l.country)).slice(0, 10),
    // Trials are frontier evidence by nature — always label their maturity for the UI.
    maturity: completed ? 'emerging' : 'experimental',
    caution: completed
      ? 'Completed trial — read the published results before acting; a single trial is not yet standard of care.'
      : 'Ongoing trial — no established efficacy yet; enrollment is not a treatment recommendation.',
  };
}

// ---------------------------------------------------------------------------
// Tool: drug_label — openFDA /drug/label.json (T0 authoritative fact)
// ---------------------------------------------------------------------------

async function tool_drug_label(args) {
  const name = String(args.name || '').trim();
  if (!name) {
    return { results: [], disclaimer: OPENFDA_DISCLAIMER, note: 'No drug name provided.' };
  }

  try {
    // Search brand name OR generic name.
    const escaped = name.replace(/"/g, '');
    const search = `(openfda.brand_name:"${escaped}"+openfda.generic_name:"${escaped}")`;
    const params = new URLSearchParams();
    params.set('search', search);
    params.set('limit', '1');
    if (process.env.ROUNDS_OPENFDA_API_KEY) {
      params.set('api_key', process.env.ROUNDS_OPENFDA_API_KEY);
    }
    const url = `${OPENFDA_BASE}?${params.toString()}`;
    const data = await generalLimiter(() => httpGetJson(url));
    const results = (data && data.results) || [];
    if (results.length === 0) {
      return {
        name,
        label: null,
        trustTier: 'T0',
        disclaimer: OPENFDA_DISCLAIMER,
        note: `No openFDA label found for "${name}".`,
      };
    }
    const r = results[0];
    const openfda = r.openfda || {};
    const label = {
      brandName: firstOf(openfda.brand_name),
      genericName: firstOf(openfda.generic_name),
      manufacturer: firstOf(openfda.manufacturer_name),
      route: firstOf(openfda.route),
      indications: joinField(r.indications_and_usage),
      dosage: joinField(r.dosage_and_administration),
      warnings: joinField(r.warnings || r.warnings_and_cautions),
      boxedWarning: joinField(r.boxed_warning),
      contraindications: joinField(r.contraindications),
      adverseReactions: joinField(r.adverse_reactions),
      drugInteractions: joinField(r.drug_interactions),
    };
    return {
      name,
      trustTier: 'T0',
      label,
      whyTrusted: 'openFDA structured product label — authoritative regulatory fact (not evidence-graded)',
      disclaimer: OPENFDA_DISCLAIMER,
      note: `openFDA label for ${label.brandName || label.genericName || name}.`,
    };
  } catch (e) {
    log('openfda error:', e.message);
    return {
      name,
      label: null,
      trustTier: 'T0',
      disclaimer: OPENFDA_DISCLAIMER,
      note: `openFDA request failed (${e.message}). Returning no label.`,
    };
  }
}

function firstOf(v) {
  if (Array.isArray(v)) return v[0] || null;
  return v || null;
}
function joinField(v) {
  if (!v) return null;
  if (Array.isArray(v)) {
    const joined = v.join('\n\n').trim();
    return joined ? truncate(joined, 4000) : null;
  }
  return truncate(String(v), 4000);
}

// ---------------------------------------------------------------------------
// Tool: dose_check — DETERMINISTIC OTC dose arithmetic (never let the model do it)
//
// LLMs are provably bad at rolling-24h dose math and confidently wrong about it
// (DOSEBENCH arXiv:2606.04262: best model 55.6% accurate at 91.5% self-confidence).
// So the model only EXTRACTS dose events; every sum, interval, and verdict is
// computed here in pure Node against a bundled FDA OTC-monograph limits table
// (openFDA's dosage_and_administration is free-text prose with no structured max).
// Rx and pediatric weight-based dosing are refused (out_of_scope), never guessed.
// ---------------------------------------------------------------------------

const MS_PER_HOUR = 3600 * 1000;
const MS_PER_DAY = 24 * MS_PER_HOUR;

// Adult OTC ceilings from the public-domain FDA OTC Drug Facts monographs. Keyed by
// canonical active ingredient. These few numbers are stable; refresh on a monograph change.
const OTC_DOSE_TABLE = {
  acetaminophen: {
    max_daily_mg: 4000, min_interval_hours: 4, max_single_mg: 1000,
    source: 'FDA OTC Drug Facts monograph (adult acetaminophen)',
    brand_note: 'Some brands voluntarily label a lower 3000–3250 mg/day cap; 4000 mg is the monograph maximum. Chronic use or alcohol lowers the safe ceiling.',
    synonyms: ['acetaminophen', 'paracetamol', 'tylenol', 'apap', 'panadol', 'mapap', 'feverall', 'tempra'],
  },
  ibuprofen: {
    max_daily_mg: 1200, min_interval_hours: 4, max_single_mg: 400,
    source: 'FDA OTC Drug Facts monograph (adult ibuprofen, OTC self-care ceiling)',
    brand_note: 'OTC self-care ceiling is 1200 mg/day; higher (up to 3200 mg/day) is prescription-only and clinician-supervised.',
    synonyms: ['ibuprofen', 'advil', 'motrin', 'nurofen', 'brufen', 'midol ib'],
  },
  naproxen: {
    max_daily_mg: 660, min_interval_hours: 8, max_single_mg: 220,
    source: 'FDA OTC Drug Facts monograph (adult naproxen sodium, OTC)',
    brand_note: 'OTC ceiling is 660 mg/day naproxen sodium (220 mg every 8–12h); prescription doses are higher.',
    synonyms: ['naproxen', 'naproxen sodium', 'aleve', 'naprosyn', 'anaprox'],
  },
  aspirin: {
    max_daily_mg: 4000, min_interval_hours: 4, max_single_mg: 1000,
    source: 'FDA OTC Drug Facts monograph (adult analgesic aspirin)',
    brand_note: 'Analgesic OTC ceiling is ~4000 mg/day. Low-dose cardioprotective aspirin (75–100 mg daily) is a SEPARATE regimen — this tool does not evaluate it.',
    synonyms: ['aspirin', 'acetylsalicylic acid', 'asa', 'bayer aspirin', 'ecotrin', 'bufferin'],
  },
};

// OTC combination brands that hide an analgesic — the #1 real-world accidental-overdose path.
// Maps a brand cue → the hidden ingredient we compute against, flagging the duplicate risk.
const OTC_COMBO_HIDDEN = {
  nyquil: 'acetaminophen', dayquil: 'acetaminophen', theraflu: 'acetaminophen',
  'tylenol pm': 'acetaminophen', 'tylenol cold': 'acetaminophen', 'tylenol sinus': 'acetaminophen',
  excedrin: 'acetaminophen', mucinex: 'acetaminophen', robitussin: 'acetaminophen',
  sudafed: 'acetaminophen', 'advil pm': 'ibuprofen', 'advil cold': 'ibuprofen',
};

const DOSE_DISCLAIMER =
  'Dose limits are the adult FDA OTC-monograph ceilings, not personalized medical advice. ' +
  'Lower limits apply with liver/kidney disease, alcohol use, low body weight, or other medicines — ' +
  'when unsure, ask a pharmacist. This tool does not evaluate prescription or weight-based pediatric dosing.';

function resolveIngredient(drugRaw) {
  const d = String(drugRaw || '').trim().toLowerCase();
  if (!d) return { matched: false };
  // 1) Direct ingredient/brand synonym match.
  for (const [ingredient, spec] of Object.entries(OTC_DOSE_TABLE)) {
    if (spec.synonyms.some((s) => d === s || d.includes(s))) {
      return { matched: true, ingredient, combination: false };
    }
  }
  // 2) Combination brand hiding an analgesic.
  for (const [cue, ingredient] of Object.entries(OTC_COMBO_HIDDEN)) {
    if (d.includes(cue)) {
      return { matched: true, ingredient, combination: true, comboBrand: cue };
    }
  }
  return { matched: false };
}

// Parse a dose time: an integer "minutes ago" (string or number), or an ISO-8601 string.
// The minutes-ago check MUST come first: V8's Date.parse("360") misreads a bare integer as
// the year 360, so a numeric "minutes ago" value would silently become an ancient timestamp.
function parseDoseAt(at, nowMs) {
  if (at === null || at === undefined || at === '') return NaN;
  if (typeof at === 'number' || (typeof at === 'string' && /^-?\d+(\.\d+)?$/.test(at.trim()))) {
    const mins = Number(at);
    return Number.isFinite(mins) ? nowMs - mins * 60 * 1000 : NaN; // minutes-ago
  }
  const iso = Date.parse(at);
  return Number.isFinite(iso) ? iso : NaN;
}

function tool_dose_check(args) {
  const a = args || {};
  const nowMs = a.now ? Date.parse(a.now) : Date.now();
  const drugRaw = String(a.drug || '').trim();

  // --- out-of-scope guards (refuse, never guess) ---
  if (!drugRaw) {
    return { verdict: 'out_of_scope', reason: 'no_drug', message: 'No drug name was provided.', disclaimer: DOSE_DISCLAIMER };
  }
  const age = a.patient_age_years !== undefined ? Number(a.patient_age_years) : null;
  if (age !== null && Number.isFinite(age) && age < 18) {
    return {
      verdict: 'out_of_scope', reason: 'pediatric',
      resolved: { input: drugRaw },
      message: 'Pediatric dosing is weight- and age-based and varies by product — this tool only covers adult OTC ceilings. Use the product’s pediatric chart or ask a pharmacist/clinician.',
      disclaimer: DOSE_DISCLAIMER,
    };
  }
  const res = resolveIngredient(drugRaw);
  if (!res.matched) {
    return {
      verdict: 'out_of_scope', reason: 'unknown_or_prescription',
      resolved: { input: drugRaw, matched: false },
      message: `“${drugRaw}” is not a recognized adult OTC analgesic/antipyretic (acetaminophen, ibuprofen, naproxen, aspirin). It may be prescription-only or combination — do not estimate; check the label or ask a pharmacist.`,
      disclaimer: DOSE_DISCLAIMER,
    };
  }
  const limits = OTC_DOSE_TABLE[res.ingredient];

  // --- parse dose events (the model's only job was extraction) ---
  const rawDoses = Array.isArray(a.doses) ? a.doses : [];
  const parsed = [];
  let unparsed = 0;
  for (const dz of rawDoses) {
    const ms = parseDoseAt(dz && dz.at, nowMs);
    const mg = Number(dz && dz.amount_mg);
    if (!Number.isFinite(ms) || !Number.isFinite(mg) || mg <= 0) { unparsed++; continue; }
    parsed.push({ ms, mg });
  }
  parsed.sort((x, y) => x.ms - y.ms);

  const proposedMg = a.proposed_mg !== undefined && Number.isFinite(Number(a.proposed_mg))
    ? Number(a.proposed_mg) : null;

  // --- rolling 24h window ending now ---
  const windowStart = nowMs - MS_PER_DAY;
  const inWindow = parsed.filter((d) => d.ms > windowStart && d.ms <= nowMs);
  const total24h = inWindow.reduce((s, d) => s + d.mg, 0);
  const remainingMg = Math.max(0, limits.max_daily_mg - total24h);

  // --- interval since last dose ---
  const lastMs = parsed.length ? parsed[parsed.length - 1].ms : null;
  const intervalOkAt = lastMs !== null ? lastMs + limits.min_interval_hours * MS_PER_HOUR : nowMs;
  const intervalOkNow = nowMs >= intervalOkAt;

  // --- earliest instant when a `proposed_mg` (or a fresh standard dose) is safe ---
  // Safe = interval has cleared AND the trailing-24h sum + proposed ≤ daily max.
  const need = proposedMg !== null ? proposedMg : 0;
  function windowSumAt(t) {
    return parsed.reduce((s, d) => (d.ms > t - MS_PER_DAY && d.ms <= t ? s + d.mg : s), 0);
  }
  const candidates = new Set([nowMs, intervalOkAt]);
  for (const d of parsed) candidates.add(d.ms + MS_PER_DAY + 1); // instant a dose leaves the 24h window
  let earliestSafe = null;
  for (const t of [...candidates].filter((t) => t >= nowMs).sort((x, y) => x - y)) {
    if (t >= intervalOkAt && windowSumAt(t) + need <= limits.max_daily_mg) { earliestSafe = t; break; }
  }
  const timeToNextSafeHours = earliestSafe !== null ? Math.max(0, (earliestSafe - nowMs) / MS_PER_HOUR) : null;

  // --- verdict (most severe wins) + collected warnings ---
  const warnings = [];
  if (res.combination) {
    warnings.push(`This looks like a combination product (${res.comboBrand}) that contains ${res.ingredient} — count it toward the ${res.ingredient} total, and check every other medicine for hidden ${res.ingredient} (a common accidental-overdose path).`);
  }
  let verdict = 'ok';
  const projected = proposedMg !== null ? total24h + proposedMg : total24h;
  if (unparsed > 0) verdict = 'need_times';
  if (proposedMg !== null && proposedMg > limits.max_single_mg) verdict = 'exceeds_single_dose';
  if (!intervalOkNow) verdict = 'interval_too_soon';
  if (projected > limits.max_daily_mg) verdict = 'exceeds_daily_max';

  let message;
  switch (verdict) {
    case 'exceeds_daily_max':
      message = `That would put the 24-hour ${res.ingredient} total at ${projected} mg, over the ${limits.max_daily_mg} mg/day limit. Do not take more now.` +
        (timeToNextSafeHours !== null ? ` The next dose fits within the limit in about ${timeToNextSafeHours.toFixed(1)}h.` : '');
      break;
    case 'interval_too_soon':
      message = `The last dose was too recent — wait at least ${limits.min_interval_hours}h between doses of ${res.ingredient}.` +
        (timeToNextSafeHours !== null ? ` Next safe dose in about ${timeToNextSafeHours.toFixed(1)}h.` : '');
      break;
    case 'exceeds_single_dose':
      message = `${proposedMg} mg is above the ${limits.max_single_mg} mg single-dose limit for OTC ${res.ingredient}.`;
      break;
    case 'need_times':
      message = `Some dose times/amounts couldn’t be read (${unparsed}). Give the time and mg of each recent dose and I’ll compute the rolling 24-hour total exactly — don’t estimate.`;
      break;
    default:
      message = proposedMg !== null
        ? `Taking ${proposedMg} mg now is within limits: 24-hour ${res.ingredient} total would be ${projected} mg of ${limits.max_daily_mg} mg, and it’s been long enough since the last dose.`
        : `So far ${total24h} mg of ${res.ingredient} in the last 24h; ${remainingMg} mg of headroom to the ${limits.max_daily_mg} mg/day limit.`;
  }

  return {
    resolved: { input: drugRaw, ingredient: res.ingredient, matched: true, combination: !!res.combination },
    limits: {
      max_daily_mg: limits.max_daily_mg, min_interval_hours: limits.min_interval_hours,
      max_single_mg: limits.max_single_mg, source: limits.source, brand_note: limits.brand_note,
    },
    rolling_24h: { window_hours: 24, doses_in_window: inWindow.length, total_mg: total24h, remaining_mg: remainingMg },
    interval: {
      last_dose_at: lastMs !== null ? new Date(lastMs).toISOString() : null,
      earliest_next_at: lastMs !== null ? new Date(intervalOkAt).toISOString() : null,
      ok_now: intervalOkNow,
    },
    proposed: proposedMg !== null ? { amount_mg: proposedMg, projected_24h_total_mg: projected, would_exceed_daily: projected > limits.max_daily_mg } : null,
    time_to_next_safe: earliestSafe !== null && timeToNextSafeHours > 0
      ? { hours: Number(timeToNextSafeHours.toFixed(2)), at: new Date(earliestSafe).toISOString() } : { hours: 0, at: new Date(nowMs).toISOString() },
    verdict,
    warnings,
    message,
    disclaimer: DOSE_DISCLAIMER,
  };
}

// ---------------------------------------------------------------------------
// Tool: rank_sources — apply the deterministic model to a caller-supplied list
// ---------------------------------------------------------------------------

async function tool_rank_sources(args) {
  const input = Array.isArray(args.citations) ? args.citations : [];
  if (input.length === 0) {
    return { citations: [], note: 'No citations provided to rank.' };
  }
  // Accept loosely-shaped citations; normalize a couple of common field aliases.
  const normalized = input.map((c) => ({
    id: c.id || (c.doi ? `doi:${c.doi}` : c.pmid ? `pmid:${c.pmid}` : undefined),
    source: c.source || 'provided',
    title: c.title || '',
    journal: c.journal || '',
    year: c.year || parseYear(c.date),
    pubTypes: c.pubTypes || c.publicationTypes || c.pubtype || [],
    meshTerms: c.meshTerms || c.mesh || [],
    url: c.url || '',
    doi: c.doi || '',
    pmid: c.pmid ? String(c.pmid) : '',
    citedBy: typeof c.citedBy === 'number' ? c.citedBy : (typeof c.citedByCount === 'number' ? c.citedByCount : undefined),
    isPreprint: !!c.isPreprint,
    commentsCorrections: c.commentsCorrections || [],
    medlineIndexed: !!c.medlineIndexed,
    _apiRelevance: typeof c.relevance === 'number' ? c.relevance : 0.6,
    _titleBoost: false,
  }));

  const ranked = rankCitations(normalized).map((c) => ({
    ...shapeCitationOut(c),
    scoreComponents: c.scoreComponents,
    tierReasons: c.tierReasons,
  }));

  const droppedRetracted = normalized.length - ranked.length;
  return {
    citations: ranked,
    note: `Ranked ${ranked.length} citation(s)${droppedRetracted > 0 ? `; dropped ${droppedRetracted} retracted` : ''}. Sorted by trust tier then score.`,
  };
}

// ---------------------------------------------------------------------------
// Small shared helpers
// ---------------------------------------------------------------------------

function parseYear(s) {
  if (!s) return null;
  const m = String(s).match(/(\d{4})/);
  return m ? Number(m[1]) : null;
}
function queryTerms(q) {
  return String(q || '')
    .toLowerCase()
    .replace(/[^a-z0-9 ]+/g, ' ')
    .split(/\s+/)
    .filter(Boolean);
}
function cleanText(s) {
  return String(s || '')
    .replace(/<[^>]+>/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}
function truncate(s, n) {
  s = String(s);
  return s.length > n ? s.slice(0, n) + '…' : s;
}
function clampInt(v, dflt, lo, hi) {
  let n = Number(v);
  if (!Number.isFinite(n)) n = dflt;
  n = Math.floor(n);
  return Math.min(hi, Math.max(lo, n));
}
function normalizeTierFilter(tf) {
  if (!tf) return null;
  const arr = Array.isArray(tf) ? tf : [tf];
  const valid = new Set(TIER_ORDER);
  return arr.map((t) => String(t).toUpperCase()).filter((t) => valid.has(t));
}

